mapper.select:
select warehouse_id from `ry_rental`.`ry_rental_user_warehouse_scope`
where tenant_id = #{tenantId} and member_id = #{merchantId} and merchant_user_id = #{userId}
order by warehouse_id

select count(1) from `ry_rental`.`ry_rental_user_member`
where tenant_id = #{tenantId} and member_id = #{merchantId} and merchant_user_id = #{userId}
  and member_role = 'owner' and del_flag = '0'

mapper.insert:
insert into `ry_rental`.`ry_rental_merchant_user_role`
(tenant_id, member_id, merchant_user_id, role_id)
select #{tenantId}, #{merchantId}, #{userId}, #{roleId}
where not exists (
    select 1 from `ry_rental`.`ry_rental_merchant_user_role`
    where tenant_id = #{tenantId} and member_id = #{merchantId}
      and merchant_user_id = #{userId} and role_id = #{roleId}
)
